#!/usr/bin/env bash
# Builds a universal Sweep.app, signs it with your Developer ID, notarizes and staples it,
# packs it into a signed, notarized DMG, publishes the DMG as a GitHub release, and bumps the
# Homebrew cask in chiranjeebhub/homebrew-tap (override with SWEEP_TAP=owner/repo).
#
# Usage: scripts/release.sh <version> [options]
#   --notes <file>   Release notes (Markdown). Default: notes generated by GitHub from the commits.
#   --draft          Create the GitHub release as a draft.
#   --no-publish     Stop after the DMG is notarized. Nothing is pushed or published.
#   --no-notarize    Skip notarization too (for checking signing and the DMG). Implies --no-publish.
#   --no-cask        Don't update the Homebrew cask (drafts never update it).
#   --yes            Don't ask before publishing.
#
# Credentials come from the environment or the keychain, never from this repo:
#   SWEEP_SIGN_IDENTITY  Codesigning identity. Default: the first "Developer ID Application" in the keychain.
#   NOTARY_PROFILE       notarytool keychain profile (default: sweep-notary), made with `notarytool store-credentials`.
#   Or, instead of a profile, an App Store Connect API key:
#     NOTARY_KEY_PATH, NOTARY_KEY_ID, NOTARY_ISSUER
#   Or an Apple ID with an app-specific password:
#     NOTARY_APPLE_ID, NOTARY_TEAM_ID, NOTARY_PASSWORD
# See docs/RELEASING.md for the one-time setup.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
APP="$ROOT/build/Sweep.app"
DIST="$ROOT/dist"
ENTITLEMENTS="$ROOT/Resources/Sweep.entitlements"

VERSION=""
NOTES=""
DRAFT=0
PUBLISH=1
NOTARIZE=1
ASSUME_YES=0
CASK=1
TAP_REPO="${SWEEP_TAP:-chiranjeebhub/homebrew-tap}"

die() { echo "error: $*" >&2; exit 1; }
step() { echo; echo "==> $*"; }

while [ $# -gt 0 ]; do
    case "$1" in
        --notes) NOTES="${2:?--notes needs a file}"; shift ;;
        --draft) DRAFT=1 ;;
        --no-publish) PUBLISH=0 ;;
        --no-notarize) NOTARIZE=0; PUBLISH=0 ;;
        --no-cask) CASK=0 ;;
        --yes) ASSUME_YES=1 ;;
        -h|--help) sed -n '2,21p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        -*) die "unknown option $1" ;;
        *) [ -z "$VERSION" ] || die "version given twice"; VERSION="$1" ;;
    esac
    shift
done

[ -n "$VERSION" ] || die "usage: scripts/release.sh <version> [--notes file] [--draft] [--no-publish] [--no-notarize] [--no-cask] [--yes]"
VERSION="${VERSION#v}"
[[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+([-.][0-9A-Za-z.]+)?$ ]] || die "version must look like 1.2.3, got $VERSION"
TAG="v$VERSION"
DMG="$DIST/Sweep-$VERSION.dmg"
[ -z "$NOTES" ] || [ -f "$NOTES" ] || die "notes file not found: $NOTES"

cd "$ROOT"

# --- Preflight: fail before the slow steps, not after them -------------------------------------
step "Checking tools and credentials"
for tool in swift codesign hdiutil xcrun /usr/libexec/PlistBuddy; do
    command -v "$tool" >/dev/null || die "$tool not found (install Xcode and its command line tools)"
done

if [ -z "${SWEEP_SIGN_IDENTITY:-}" ]; then
    SWEEP_SIGN_IDENTITY="$(security find-identity -v -p codesigning \
        | sed -n 's/.*"\(Developer ID Application: .*\)"/\1/p' | head -n 1)"
    [ -n "$SWEEP_SIGN_IDENTITY" ] || die "no Developer ID Application certificate in the keychain (see docs/RELEASING.md)"
fi
echo "Signing as: $SWEEP_SIGN_IDENTITY"

NOTARY_ARGS=()
if [ "$NOTARIZE" = 1 ]; then
    if [ -n "${NOTARY_KEY_PATH:-}" ]; then
        [ -n "${NOTARY_KEY_ID:-}" ] && [ -n "${NOTARY_ISSUER:-}" ] || die "NOTARY_KEY_PATH also needs NOTARY_KEY_ID and NOTARY_ISSUER"
        NOTARY_ARGS=(--key "$NOTARY_KEY_PATH" --key-id "$NOTARY_KEY_ID" --issuer "$NOTARY_ISSUER")
        echo "Notarizing with API key $NOTARY_KEY_ID"
    elif [ -n "${NOTARY_APPLE_ID:-}" ]; then
        [ -n "${NOTARY_TEAM_ID:-}" ] && [ -n "${NOTARY_PASSWORD:-}" ] || die "NOTARY_APPLE_ID also needs NOTARY_TEAM_ID and NOTARY_PASSWORD"
        NOTARY_ARGS=(--apple-id "$NOTARY_APPLE_ID" --team-id "$NOTARY_TEAM_ID" --password "$NOTARY_PASSWORD")
        echo "Notarizing as $NOTARY_APPLE_ID"
    else
        NOTARY_PROFILE="${NOTARY_PROFILE:-sweep-notary}"
        NOTARY_ARGS=(--keychain-profile "$NOTARY_PROFILE")
        xcrun notarytool history "${NOTARY_ARGS[@]}" >/dev/null 2>&1 \
            || die "notarytool profile \"$NOTARY_PROFILE\" doesn't work. Run: xcrun notarytool store-credentials $NOTARY_PROFILE (see docs/RELEASING.md)"
        echo "Notarizing with keychain profile $NOTARY_PROFILE"
    fi
fi

if [ "$PUBLISH" = 1 ]; then
    command -v gh >/dev/null || die "gh not found. Install it with: brew install gh"
    gh auth status >/dev/null 2>&1 || die "gh isn't signed in. Run: gh auth login"
    [ -z "$(git status --porcelain)" ] || die "working tree has uncommitted changes; commit or stash them first"
    git fetch --quiet origin main
    [ "$(git rev-parse HEAD)" = "$(git rev-parse origin/main)" ] || die "HEAD isn't origin/main; release from an up-to-date, pushed main"
    if gh release view "$TAG" >/dev/null 2>&1; then die "release $TAG already exists on GitHub"; fi
fi

# --- Build -------------------------------------------------------------------------------------
step "Building universal Sweep.app $VERSION"
BUILD_NUMBER="$(git rev-list --count HEAD)"
SWEEP_ARCHS="arm64 x86_64" SWEEP_VERSION="$VERSION" SWEEP_BUILD="$BUILD_NUMBER" \
    "$ROOT/scripts/build-app.sh" release
echo "Version $VERSION (build $BUILD_NUMBER), architectures: $(lipo -archs "$APP/Contents/MacOS/Sweep")"

# --- Sign --------------------------------------------------------------------------------------
step "Signing with hardened runtime"
# Drop build-app.sh's ad-hoc signature and any Finder metadata, so the Developer ID signature starts clean.
codesign --remove-signature "$APP"
xattr -cr "$APP"
codesign --force --timestamp --options runtime \
    --entitlements "$ENTITLEMENTS" \
    --sign "$SWEEP_SIGN_IDENTITY" "$APP"
codesign --verify --strict --verbose=2 "$APP"

notarize() {
    local file="$1" result="$DIST/notary-result.plist" id status
    xcrun notarytool submit "$file" "${NOTARY_ARGS[@]}" --wait --output-format plist > "$result" \
        || { cat "$result" >&2; die "notarytool submit failed for $(basename "$file")"; }
    id="$(/usr/libexec/PlistBuddy -c "Print :id" "$result")"
    status="$(/usr/libexec/PlistBuddy -c "Print :status" "$result")"
    rm -f "$result"
    echo "Submission $id: $status"
    if [ "$status" != "Accepted" ]; then
        xcrun notarytool log "$id" "${NOTARY_ARGS[@]}" >&2 || true
        die "Apple didn't accept $(basename "$file") (log above)"
    fi
}

mkdir -p "$DIST"

# Notarize and staple the app itself first, so a copy dragged out of the DMG
# still passes Gatekeeper when the Mac is offline.
if [ "$NOTARIZE" = 1 ]; then
    step "Notarizing Sweep.app (this usually takes a few minutes)"
    ZIP="$DIST/Sweep-$VERSION-notarize.zip"
    rm -f "$ZIP"
    ditto -c -k --keepParent "$APP" "$ZIP"
    notarize "$ZIP"
    rm -f "$ZIP"
    xcrun stapler staple "$APP"
fi

# --- DMG ---------------------------------------------------------------------------------------
step "Creating $(basename "$DMG")"
STAGING="$(mktemp -d)"
trap 'rm -rf "$STAGING"' EXIT
ditto "$APP" "$STAGING/Sweep.app"
ln -s /Applications "$STAGING/Applications"
rm -f "$DMG"
hdiutil create -volname "Sweep $VERSION" -srcfolder "$STAGING" -fs HFS+ -format UDZO -ov "$DMG" >/dev/null
codesign --force --timestamp --sign "$SWEEP_SIGN_IDENTITY" "$DMG"

if [ "$NOTARIZE" = 1 ]; then
    step "Notarizing the DMG"
    notarize "$DMG"
    xcrun stapler staple "$DMG"
    xcrun stapler validate "$DMG"
    spctl --assess --type open --context context:primary-signature --verbose=2 "$DMG"
    spctl --assess --type execute --verbose=2 "$APP"
fi

(cd "$DIST" && shasum -a 256 "$(basename "$DMG")" > "$(basename "$DMG").sha256")
echo "SHA-256: $(cut -d' ' -f1 "$DMG.sha256")"

if [ "$PUBLISH" = 0 ]; then
    step "Done: $DMG (not published)"
    exit 0
fi

# --- Publish -----------------------------------------------------------------------------------
KIND="public release"; [ "$DRAFT" = 1 ] && KIND="draft release"
if [ "$ASSUME_YES" = 0 ]; then
    printf '\nPublish %s as a %s on GitHub? [y/N] ' "$TAG" "$KIND"
    read -r answer
    [[ "$answer" =~ ^[Yy] ]] || { echo "Not published. The DMG is at $DMG"; exit 0; }
fi

step "Publishing $TAG"
GH_ARGS=(--title "Sweep $VERSION" --target "$(git rev-parse HEAD)")
if [ -n "$NOTES" ]; then GH_ARGS+=(--notes-file "$NOTES"); else GH_ARGS+=(--generate-notes); fi
[ "$DRAFT" = 1 ] && GH_ARGS+=(--draft)
gh release create "$TAG" "$DMG" "$DMG.sha256" "${GH_ARGS[@]}"

# --- Homebrew cask -----------------------------------------------------------------------------
if [ "$DRAFT" = 1 ] || [ "$CASK" = 0 ]; then
    echo "Homebrew cask not updated."
    exit 0
fi

step "Updating Casks/sweep.rb in $TAP_REPO"
TAP="$STAGING/tap"
SHA="$(cut -d' ' -f1 "$DMG.sha256")"
gh repo clone "$TAP_REPO" "$TAP" -- --depth 1 --quiet
[ -f "$TAP/Casks/sweep.rb" ] || die "$TAP_REPO has no Casks/sweep.rb; add it once by hand (the release itself is published)"
sed -i '' -e "s/^  version \".*\"/  version \"$VERSION\"/" -e "s/^  sha256 \".*\"/  sha256 \"$SHA\"/" "$TAP/Casks/sweep.rb"
git -C "$TAP" add Casks/sweep.rb
git -C "$TAP" commit --quiet -m "Update Sweep to $VERSION"
git -C "$TAP" -c credential.helper='!gh auth git-credential' push --quiet origin HEAD
echo "Cask updated: brew upgrade --cask chiranjeebhub/tap/sweep"
